// ring-buffer | enqueue-dequeue / modular-index | large / p2

#include <stdbool.h>
#include <stdio.h>

typedef struct {
    int data[12];
    size_t head;
    size_t tail;
    size_t count;
} RingBuffer;

static bool ring_push(RingBuffer *ring, int value) {
    if (ring->count == 12U) return false;
    ring->data[ring->tail] = value;
    ring->tail = (ring->tail + 1U) % 12U;
    ring->count++;
    return true;
}

static bool ring_pop(RingBuffer *ring, int *out) {
    if (ring->count == 0U) return false;
    *out = ring->data[ring->head];
    ring->head = (ring->head + 1U) % 12U;
    ring->count--;
    return true;
}

int main(void) {
    RingBuffer ring = { .head = 0, .tail = 0, .count = 0 };
    printf("push %d -> %d\n", 1000, ring_push(&ring, 1000));
    printf("push %d -> %d\n", 1003, ring_push(&ring, 1003));
    printf("push %d -> %d\n", 1006, ring_push(&ring, 1006));
    printf("push %d -> %d\n", 1009, ring_push(&ring, 1009));
    printf("push %d -> %d\n", 1012, ring_push(&ring, 1012));
    printf("push %d -> %d\n", 1015, ring_push(&ring, 1015));
    printf("push %d -> %d\n", 1018, ring_push(&ring, 1018));
    printf("push %d -> %d\n", 1021, ring_push(&ring, 1021));
    printf("push %d -> %d\n", 1024, ring_push(&ring, 1024));
    printf("push %d -> %d\n", 1027, ring_push(&ring, 1027));
    printf("push %d -> %d\n", 1030, ring_push(&ring, 1030));
    printf("push %d -> %d\n", 1033, ring_push(&ring, 1033));

    int value = 0;
    while (ring_pop(&ring, &value)) {
        printf("pop %d\n", value);
    }
    return 0;
}

