#include <stdbool.h>
#include <stdio.h>

typedef struct {
    int data[12];
    size_t head;
    size_t tail;
    size_t count;
} RingBuffer;

static bool ring_push(RingBuffer *ring, int value) {
    if (ring->count == 12U) return false;
    ring->data[ring->tail] = value;
    ring->tail = (ring->tail + 1U) % 12U;
    ring->count++;
    return true;
}

static bool ring_pop(RingBuffer *ring, int *out) {
    if (ring->count == 0U) return false;
    *out = ring->data[ring->head];
    ring->head = (ring->head + 1U) % 12U;
    ring->count--;
    return true;
}

