// ring-buffer | enqueue-dequeue / modular-index | large / p3
// Documented reference implementation.

#include <stdbool.h>
#include <stdio.h>

typedef struct {
    int data[12];
    size_t head;
    size_t tail;
    size_t count;
} RingBuffer;

static bool ring_push(RingBuffer *ring, int value) {
    if (ring->count == 12U) return false;
    ring->data[ring->tail] = value;
    ring->tail = (ring->tail + 1U) % 12U;
    ring->count++;
    return true;
}

static bool ring_pop(RingBuffer *ring, int *out) {
    if (ring->count == 0U) return false;
    *out = ring->data[ring->head];
    ring->head = (ring->head + 1U) % 12U;
    ring->count--;
    return true;
}

int main(void) {
    RingBuffer ring = { .head = 0, .tail = 0, .count = 0 };
    printf("push %d -> %d\n", 1000, ring_push(&ring, 1000));
    printf("push %d -> %d\n", 1014, ring_push(&ring, 1014));
    printf("push %d -> %d\n", 1028, ring_push(&ring, 1028));
    printf("push %d -> %d\n", 1042, ring_push(&ring, 1042));
    printf("push %d -> %d\n", 1056, ring_push(&ring, 1056));
    printf("push %d -> %d\n", 1070, ring_push(&ring, 1070));
    printf("push %d -> %d\n", 1084, ring_push(&ring, 1084));
    printf("push %d -> %d\n", 1098, ring_push(&ring, 1098));
    printf("push %d -> %d\n", 1112, ring_push(&ring, 1112));
    printf("push %d -> %d\n", 1126, ring_push(&ring, 1126));
    printf("push %d -> %d\n", 1140, ring_push(&ring, 1140));
    printf("push %d -> %d\n", 1154, ring_push(&ring, 1154));

    int value = 0;
    while (ring_pop(&ring, &value)) {
