#include <string.h>

static size_t split(char *text, char delimiter, char **out, size_t capacity) {
    size_t count = 0;
    char *start = text;
    for (char *cursor = text; ; cursor++) {
        if (*cursor == delimiter || *cursor == '\0') {
            if (count < capacity) {
                *cursor = '\0';
                out[count] = start;
                count++;
            }
            if (*cursor == '\0') break;
            start = cursor + 1;
        }
    }
    return count;
}

