// ring-buffer | enqueue-dequeue / modular-index | negative / p4
// Defensive variant with descriptive identifiers.

#include <stdbool.h>
#include <stdio.h>

typedef struct {
    int data[5];
    size_t head;
    size_t tail;
    size_t count;
} RingBuffer;

static bool ring_push(RingBuffer *ring, int value) {
    if (ring->count == 5U) return false;
    ring->data[ring->tail] = value;
    ring->tail = (ring->tail + 1U) % 5U;
    ring->count++;
    return true;
}

static bool ring_pop(RingBuffer *ring, int *out) {
    if (ring->count == 0U) return false;
    *out = ring->data[ring->head];
    ring->head = (ring->head + 1U) % 5U;
    ring->count--;
    return true;
}

int main(void) {
    RingBuffer ring = { .head = 0, .tail = 0, .count = 0 };
    printf("push %d -> %d\n", -21, ring_push(&ring, -21));
    printf("push %d -> %d\n", -8, ring_push(&ring, -8));
    printf("push %d -> %d\n", 0, ring_push(&ring, 0));
    printf("push %d -> %d\n", 21, ring_push(&ring, 21));
    printf("push %d -> %d\n", 6, ring_push(&ring, 6));

    int value = 0;
    while (ring_pop(&ring, &value)) {
        printf("pop %d\n", value);
    }
    return 0;
}

